// The methods, by name in their facet.
const (
	MethodInitialize       = "initialize"
	MethodCall             = "call"
	MethodCallStream       = "call_stream"
	MethodLint             = "lint"
	MethodGenerate         = "generate"
	MethodRender           = "render"
	MethodResourceSetup    = "resource_setup"
	MethodResourceReset    = "resource_reset"
	MethodResourceSnapshot = "resource_snapshot"
	MethodResourceRestore  = "resource_restore"
	MethodResourceFork     = "resource_fork"
	MethodResourceTeardown = "resource_teardown"
	MethodShutdown         = "shutdown"
	MethodNode             = "node"
	MethodResource         = "resource"
	MethodSecret           = "secret"
	MethodTemp             = "temp"
	MethodLog              = "log"
)

// Caller sends a request and decodes its result.
type Caller interface {
	Call(ctx context.Context, method string, params, result any) error
}

// StreamCaller sends a request whose result streams, and decodes each item.
type StreamCaller interface {
	CallStream(ctx context.Context, method string, params any, item func(decode func(any) error) error) error
}

// Notifier sends a notification.
type Notifier interface {
	Notify(method string, params any) error
}

// Handler serves one method: it decodes its params and returns its result. A
// handler of a streamed method sends each item with StreamItem.
type Handler func(ctx context.Context, decode func(any) error) (any, error)

// Extension is what the facet heron.extension serves.
type Extension interface {
	Initialize(ctx context.Context, p *InitializeParams) (*InitializeResult, error)
	Call(ctx context.Context, p *CallParams) (Value, error)
	// A call whose result streams: each item as a Sparrow `Item`.
	CallStream(ctx context.Context, p *CallParams) (Value, error)
	Lint(ctx context.Context, p *LintParams) (*LintResult, error)
	Generate(ctx context.Context, p *GenerateParams) (*GenerateResult, error)
	Render(ctx context.Context, p *RenderParams) (*RenderResult, error)
	ResourceSetup(ctx context.Context, p *ResourceParams) (*ResourceResult, error)
	ResourceReset(ctx context.Context, p *ResourceParams) (*ResourceResult, error)
	ResourceSnapshot(ctx context.Context, p *ResourceParams) (*ResourceResult, error)
	ResourceRestore(ctx context.Context, p *ResourceParams) (*ResourceResult, error)
	ResourceFork(ctx context.Context, p *ResourceParams) (*ResourceResult, error)
	ResourceTeardown(ctx context.Context, p *ResourceParams) (*ResourceResult, error)
	Shutdown(ctx context.Context, p *Empty) (*Empty, error)
}

// ExtensionClient calls a peer that serves Extension.
type ExtensionClient struct{ C Caller }

func (c ExtensionClient) Initialize(ctx context.Context, p *InitializeParams) (*InitializeResult, error) {
	var out InitializeResult
	err := c.C.Call(ctx, "initialize", p, &out)
	return &out, err
}

func (c ExtensionClient) Call(ctx context.Context, p *CallParams) (Value, error) {
	var out Value
	err := c.C.Call(ctx, "call", p, &out)
	return out, err
}

func (c ExtensionClient) CallStream(ctx context.Context, p *CallParams, item func(Value) error) error {
	return c.C.(StreamCaller).CallStream(ctx, "call_stream", p, func(decode func(any) error) error {
		var v Value
		if err := decode(&v); err != nil {
			return err
		}
		return item(v)
	})
}

func (c ExtensionClient) Lint(ctx context.Context, p *LintParams) (*LintResult, error) {
	var out LintResult
	err := c.C.Call(ctx, "lint", p, &out)
	return &out, err
}

func (c ExtensionClient) Generate(ctx context.Context, p *GenerateParams) (*GenerateResult, error) {
	var out GenerateResult
	err := c.C.Call(ctx, "generate", p, &out)
	return &out, err
}

func (c ExtensionClient) Render(ctx context.Context, p *RenderParams) (*RenderResult, error) {
	var out RenderResult
	err := c.C.Call(ctx, "render", p, &out)
	return &out, err
}

func (c ExtensionClient) ResourceSetup(ctx context.Context, p *ResourceParams) (*ResourceResult, error) {
	var out ResourceResult
	err := c.C.Call(ctx, "resource_setup", p, &out)
	return &out, err
}

func (c ExtensionClient) ResourceReset(ctx context.Context, p *ResourceParams) (*ResourceResult, error) {
	var out ResourceResult
	err := c.C.Call(ctx, "resource_reset", p, &out)
	return &out, err
}

func (c ExtensionClient) ResourceSnapshot(ctx context.Context, p *ResourceParams) (*ResourceResult, error) {
	var out ResourceResult
	err := c.C.Call(ctx, "resource_snapshot", p, &out)
	return &out, err
}

func (c ExtensionClient) ResourceRestore(ctx context.Context, p *ResourceParams) (*ResourceResult, error) {
	var out ResourceResult
	err := c.C.Call(ctx, "resource_restore", p, &out)
	return &out, err
}

func (c ExtensionClient) ResourceFork(ctx context.Context, p *ResourceParams) (*ResourceResult, error) {
	var out ResourceResult
	err := c.C.Call(ctx, "resource_fork", p, &out)
	return &out, err
}

func (c ExtensionClient) ResourceTeardown(ctx context.Context, p *ResourceParams) (*ResourceResult, error) {
	var out ResourceResult
	err := c.C.Call(ctx, "resource_teardown", p, &out)
	return &out, err
}

func (c ExtensionClient) Shutdown(ctx context.Context, p *Empty) (*Empty, error) {
	var out Empty
	err := c.C.Call(ctx, "shutdown", p, &out)
	return &out, err
}

// ExtensionHandlers serves an implementation of Extension by method name.
func ExtensionHandlers(impl Extension) map[string]Handler {
	return map[string]Handler{
		"initialize": func(ctx context.Context, decode func(any) error) (any, error) {
			var p InitializeParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Initialize(ctx, &p)
		},
		"call": func(ctx context.Context, decode func(any) error) (any, error) {
			var p CallParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Call(ctx, &p)
		},
		"call_stream": func(ctx context.Context, decode func(any) error) (any, error) {
			var p CallParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.CallStream(ctx, &p)
		},
		"lint": func(ctx context.Context, decode func(any) error) (any, error) {
			var p LintParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Lint(ctx, &p)
		},
		"generate": func(ctx context.Context, decode func(any) error) (any, error) {
			var p GenerateParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Generate(ctx, &p)
		},
		"render": func(ctx context.Context, decode func(any) error) (any, error) {
			var p RenderParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Render(ctx, &p)
		},
		"resource_setup": func(ctx context.Context, decode func(any) error) (any, error) {
			var p ResourceParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.ResourceSetup(ctx, &p)
		},
		"resource_reset": func(ctx context.Context, decode func(any) error) (any, error) {
			var p ResourceParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.ResourceReset(ctx, &p)
		},
		"resource_snapshot": func(ctx context.Context, decode func(any) error) (any, error) {
			var p ResourceParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.ResourceSnapshot(ctx, &p)
		},
		"resource_restore": func(ctx context.Context, decode func(any) error) (any, error) {
			var p ResourceParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.ResourceRestore(ctx, &p)
		},
		"resource_fork": func(ctx context.Context, decode func(any) error) (any, error) {
			var p ResourceParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.ResourceFork(ctx, &p)
		},
		"resource_teardown": func(ctx context.Context, decode func(any) error) (any, error) {
			var p ResourceParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.ResourceTeardown(ctx, &p)
		},
		"shutdown": func(ctx context.Context, decode func(any) error) (any, error) {
			var p Empty
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Shutdown(ctx, &p)
		},
	}
}

// Host is what the facet heron.host serves.
type Host interface {
	// The node at a path, or null when nothing is there.
	Node(ctx context.Context, p *NodeParams) (*Node, error)
	Call(ctx context.Context, p *CallParams) (Value, error)
	Resource(ctx context.Context, p *NameParams) (Value, error)
	Secret(ctx context.Context, p *NameParams) (string, error)
	Temp(ctx context.Context, p *NameParams) (string, error)
}

// HostClient calls a peer that serves Host.
type HostClient struct{ C Caller }

func (c HostClient) Node(ctx context.Context, p *NodeParams) (*Node, error) {
	var out Node
	err := c.C.Call(ctx, "node", p, &out)
	return &out, err
}

func (c HostClient) Call(ctx context.Context, p *CallParams) (Value, error) {
	var out Value
	err := c.C.Call(ctx, "call", p, &out)
	return out, err
}

func (c HostClient) Resource(ctx context.Context, p *NameParams) (Value, error) {
	var out Value
	err := c.C.Call(ctx, "resource", p, &out)
	return out, err
}

func (c HostClient) Secret(ctx context.Context, p *NameParams) (string, error) {
	var out string
	err := c.C.Call(ctx, "secret", p, &out)
	return out, err
}

func (c HostClient) Temp(ctx context.Context, p *NameParams) (string, error) {
	var out string
	err := c.C.Call(ctx, "temp", p, &out)
	return out, err
}

// HostHandlers serves an implementation of Host by method name.
func HostHandlers(impl Host) map[string]Handler {
	return map[string]Handler{
		"node": func(ctx context.Context, decode func(any) error) (any, error) {
			var p NodeParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Node(ctx, &p)
		},
		"call": func(ctx context.Context, decode func(any) error) (any, error) {
			var p CallParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Call(ctx, &p)
		},
		"resource": func(ctx context.Context, decode func(any) error) (any, error) {
			var p NameParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Resource(ctx, &p)
		},
		"secret": func(ctx context.Context, decode func(any) error) (any, error) {
			var p NameParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Secret(ctx, &p)
		},
		"temp": func(ctx context.Context, decode func(any) error) (any, error) {
			var p NameParams
			if err := decode(&p); err != nil {
				return nil, err
			}
			return impl.Temp(ctx, &p)
		},
	}
}

// A line for heron's log, sent without an answer.
func NotifyLog(n Notifier, p *LogParams) error { return n.Notify("log", p) }
